parameters.functionScript:
// Turns the raw nav items array into what each Nav Item needs,
// computing Selected from the current path (active-route highlighting).
// Every input is guarded: an unconnected input is undefined.
const asArray = (v) => Array.isArray(v) ? v : (v && Array.isArray(v.items) ? v.items : []);
const read = (item, key) => (item && typeof item.get === 'function') ? item.get(key) : (item ? item[key] : undefined);

const connected = asArray(Inputs.Items);
const source = connected.length > 0 ? connected : asArray(Inputs.Fallback);
const path = typeof Inputs.CurrentPath === 'string' ? Inputs.CurrentPath : undefined;

Outputs.Items = source.map((item) => {
    const rawTarget = read(item, 'Target');
    const target = typeof rawTarget === 'string' ? rawTarget : '';
    const isHome = read(item, 'IsHome') === true || target === '/';
    const selected = path !== undefined && (
        (path === '/' && isHome) ||
        (path !== '/' && target !== '' && target !== '/' && path.startsWith(target))
    );
    return {
        Label: read(item, 'Label'),
        Icon: read(item, 'Icon'),
        Target: target,
        Selected: selected
    };
});

const onUrlChange = () => {
    // Send the current pathname as an output
    Outputs.PathName = document.location.pathname
}

// Detect a change of the pathname
if (window.history && window.history.pushState) {
    window.addEventListener('popstate', onUrlChange)
} else {
    window.addEventListener('hashchange', onUrlChange)
}

onUrlChange()

// Responsive collapse: below the breakpoint the sidebar hides and the
// hamburger appears; opening the mobile menu shows the sidebar again.
// Every input is guarded: an unconnected input is undefined.
const bp = (typeof Inputs.Breakpoint === 'number' && Inputs.Breakpoint > 0) ? Inputs.Breakpoint : 768;
const width = (typeof Inputs.Width === 'number' && Inputs.Width > 0) ? Inputs.Width : bp + 1;
const narrow = width < bp;
Outputs.ShowHamburger = narrow;
Outputs.ShowSidebar = !narrow || Inputs.MenuOpen === true;

Outputs.IconSource = {
    "class": "material-icons",
    "code": Inputs.IconCode
}
Outputs.HaveIcon = Inputs.IconCode !== undefined && Inputs.IconCode !== ""
